package net.flashlight.battery;
import fixture.Checks;import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.world.phys.Vec3;import net.minecraft.world.level.ClipContext;import net.minecraft.world.item.ItemStack;import net.minecraft.resources.ResourceLocation;
public class ShadowChecks6{static int n;static void ok(boolean b,String m){n++;if(!b)throw new AssertionError(m);}public static class World extends Checks.World{List<Actor>players=new ArrayList<>();int queries;public Iterable<Actor>players(){return players;}public Hit clip(ClipContext c){queries++;double dz=c.to().z-c.from().z;if(c.from().z<5&&c.to().z>=5){double t=(5-c.from().z)/dz;return new Hit(new Vec3(c.from().x+(c.to().x-c.from().x)*t,c.from().y+(c.to().y-c.from().y)*t,5));}return new Hit(null);}}public record Hit(Vec3 getLocation){public String getType(){return getLocation==null?"MISS":"BLOCK";}}public static class Actor extends Checks.Player{double x,y,z;public Vec3 getEyePosition(){return new Vec3(x,y+1.62,z);}public Vec3 getEyePosition(float partial){return getEyePosition();}public Vec3 getLookAngle(){return new Vec3(0,0,1);}public Vec3 getViewVector(float partial){return getLookAngle();}public double getX(){return x;}public double getY(){return y;}public double getZ(){return z;}}
 static ItemStack s(String id){return new ItemStack(ResourceLocation.parse(id),1);}public static void main(String[]args){var mc=Minecraft.INSTANCE;var w=new World();var p=new Actor();p.world=w;p.main=s("flashlight:flashlight");Power.charge(p.main,100);mc.player=p;mc.level=w;w.players.add(p);for(int tick=0;tick<12;tick++){int before=w.queries;Light6.tick();ok(Light6.lastRays<=48&&w.queries-before<=48,"hard collision-ray budget per client tick");}ok(Light6.cache.size()==1,"only active held lamps become sources");var lamp=Light6.cache.get(p);for(float d:lamp.distance)ok(Math.abs(d-4.88)<.001,"shadow texture stores wall axial distance, not radial banding");double[]origin=lamp.origin.clone();p.x=3;Light6.render(.5f);ok(lamp.origin[0]>origin[0]+2.9,"render pose follows player position independently of isometric camera");var q=new Actor();q.world=w;q.main=s("flashlight:tactical");Power.charge(q.main,100);w.players.add(q);var third=new Actor();third.main=s("flashlight:eco");w.players.add(third);for(int i=0;i<15;i++){int before=w.queries;Light6.tick();ok(Light6.cache.size()<=2&&w.queries-before<=48,"extra players cannot exceed source or ray cap");}p.main=s("flashlight:flashlight_off");q.main=s("flashlight:tactical_off");third.main=s("flashlight:eco_off");Light6.tick();ok(Light6.cache.isEmpty(),"turning off removes all sources without stale light");mc.player=null;mc.level=null;Light6.tick();ok(Light6.cache.isEmpty()&&Light6.lastRays==0,"world unload clears cached source references");System.out.println("SHADOW_BLOCK_OCCLUSION_PLAYER_ORIGIN_BUDGET_CACHE_CHECKS="+n);}}
